int main(int argc,char**argv){try{need(argc==2,"states path required");RunManifest m;m.id="gait_geometry";m.robot=toeModel();crowResearchWingInertia(m.robot);m.scene=makeBirdFlowAmericanCrowFlightScenePack();m.sensors.id="proprioception";m.task=makeAmericanCrowEmbodiedTaskPack(m.sensors.observation,m.reality.reset);m.reality.id="reality";m.teacher.id="no_teacher";m.profile.id="probe";m.profile.capacities={.candidatePairs=512,.rawContacts=2048,.manifolds=512,.constraintBlocks=2048,.constraintRows=6144};m.task.capacities=m.profile.capacities;m.profile.environmentCount=1;m.profile.controlSteps=1;m.profile.physicsSubsteps=16;m.profile.controlTimestepSeconds=.02f;CompiledRun run;auto built=compileRun(m,run);need(built.succeeded(),built.message);auto& model=run.model();unsigned nq=model.articulations[0].nq,nv=model.articulations[0].nv;need(nq==39&&nv==38,"unexpected model");std::ifstream in(argv[1]);need(bool(in),"missing input");int lane,step;while(in>>lane>>step){std::vector<double> q(nq),v(nv);for(auto& x:q)need(bool(in>>x),"bad q");for(auto& x:v)need(bool(in>>x),"bad v");std::vector<ArticulatedBodyKinematics> k(model.articulations[0].bodyCount);auto st=computeArticulatedBodyKinematics(model,0,q,v,k);need(st.succeeded(),"kinematics failure");for(unsigned bi=0;bi<33;bi++){if(bi!=10&&bi!=13&&bi<17)continue;std::cout<<lane<<" "<<step<<" "<<model.bodyNames[bi];for(double x:k[bi].centerOfMassPosition)std::cout<<" "<<std::setprecision(12)<<x;for(double x:k[bi].orientation)std::cout<<" "<<x;std::cout<<"\n";}}}catch(const std::exception&e){std::cerr<<"failure "<<e.what()<<"\n";return 1;}}
